| extend LUN = "OS Disk"
| union dataDiskMetrics, tempDiskMetrics
| where isnotempty(TimestampUtc)
| extend Max = column_ifexists("Max",0)
| project TimestampUtc, tostring(LUN), QD = Max
| summarize QD = sum(QD) by TimestampUtc

